import{_ as e,o as t,a as r,d as o}from"./chunks/framework.IehvnstE.js";const p=JSON.parse('{"title":"Конструктор","description":"Конструктор Stuzhik: собрать модпак без установки — состав, каталог, проверка совместимости и граф зависимостей, конфиги, экспорт в .stzhk и тестовый запуск.","frontmatter":{"description":"Конструктор Stuzhik: собрать модпак без установки — состав, каталог, проверка совместимости и граф зависимостей, конфиги, экспорт в .stzhk и тестовый запуск.","head":[["meta",{"name":"keywords","content":"stuzhik конструктор, создать модпак, сборка без установки, проверка совместимости модов, граф зависимостей, экспорт stzhk"}]]},"headers":[],"relativePath":"guide/builder.md","filePath":"guide/builder.md"}'),i={name:"guide/builder.md"};function l(n,a,s,h,d,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="конструктор" tabindex="-1">Конструктор <a class="header-anchor" href="#конструктор" aria-label="Permalink to &quot;Конструктор&quot;">​</a></h1><p>Модпак, который собирают как проект, ничего не ставя: на диск не ложится ни Minecraft, ни моды, пока проект не станет экземпляром.</p><p>В проекте хранятся список модов с закреплёнными версиями, ресурспаки, шейдеры и конфиги. Готовый проект можно поставить себе экземпляром, выгрузить в <code>.stzhk</code> или опробовать тестовым запуском.</p><h2 id="новыи-проект" tabindex="-1">Новый проект <a class="header-anchor" href="#новыи-проект" aria-label="Permalink to &quot;Новый проект&quot;">​</a></h2><ol><li>«Конструктор» в боковой панели → «Создать проект»</li><li>Название, версия Minecraft и загрузчик</li><li>«Создать»</li></ol><p>Модпак Modrinth тоже можно сделать проектом: кнопка «Импорт .mrpack».</p><h2 id="состав" tabindex="-1">Состав <a class="header-anchor" href="#состав" aria-label="Permalink to &quot;Состав&quot;">​</a></h2><p>Вкладка «Состав»: то, что войдёт в модпак, по разделам «Моды», «Ресурспаки», «Шейдеры». У каждого мода:</p><ul><li><strong>Включён или выключен.</strong> Выключенный остаётся в проекте, в экземпляр ляжет выключенным, в экспорт не попадёт</li><li><strong>Обязательный или необязательный.</strong> Пометка для тех, кто будет ставить модпак</li><li><strong>Сторона.</strong> «Клиент», «Сервер» или «Обе»</li></ul><p>Сверху поиск по составу и общий вес модпака.</p><h2 id="каталог" tabindex="-1">Каталог <a class="header-anchor" href="#каталог" aria-label="Permalink to &quot;Каталог&quot;">​</a></h2><p>Вкладка «Каталог» ищет по Modrinth и CurseForge сразу под версию Minecraft и загрузчик проекта. Обязательные зависимости добавляются вместе с модом, а <strong>несовместимый мод не добавится</strong>: лаунчер скажет, с чем он конфликтует.</p><h2 id="совместимость" tabindex="-1">Совместимость <a class="header-anchor" href="#совместимость" aria-label="Permalink to &quot;Совместимость&quot;">​</a></h2><p><strong>Проверка работает без установки</strong>: по тому, что версии модов объявили на Modrinth и CurseForge, и по описанию внутри самого <code>.jar</code>, где записаны допустимые версии других модов.</p><ul><li><strong>«Проблемы»</strong>: чего не хватает (недостающую зависимость можно добавить одной кнопкой) и что не встанет вместе. Моды, положенные файлом или без версии, проверить нельзя: они перечислены отдельно</li><li><strong>«Граф зависимостей»</strong>: связи модов проекта, кто от кого зависит и что с чем несовместимо</li></ul><h2 id="конфиги" tabindex="-1">Конфиги <a class="header-anchor" href="#конфиги" aria-label="Permalink to &quot;Конфиги&quot;">​</a></h2><p>Вкладка «Конфиги»: файлы настроек модов, которые поедут вместе с модпаком, в экспорт и в экземпляр. Правка прямо в лаунчере или «Открыть в VS Code». У каждого файла есть <strong>история изменений</strong>: видно, что поменялось, и можно вернуть прежнее.</p><h2 id="готовыи-модпак" tabindex="-1">Готовый модпак <a class="header-anchor" href="#готовыи-модпак" aria-label="Permalink to &quot;Готовый модпак&quot;">​</a></h2><ul><li><strong>«Тестовый запуск»</strong> быстро создаёт экземпляр <code>[TEST] &lt;название&gt;</code> с модами и конфигами проекта, чтобы опробовать модпак в игре</li><li><strong>Экспорт → «Создать экземпляр»</strong>: то же, но со своим именем</li><li><strong>Экспорт → «Экспорт в .stzhk»</strong>: файл модпака. С галочкой «Встроить моды в архив» файл больше, зато при установке не нужен интернет; без неё моды скачиваются при установке</li></ul><p>Название, версия, автор и описание модпака задаются во вкладке «Настройки».</p><h2 id="собрать-вместе-с-друзьями" tabindex="-1">Собрать вместе с друзьями <a class="header-anchor" href="#собрать-вместе-с-друзьями" aria-label="Permalink to &quot;Собрать вместе с друзьями&quot;">​</a></h2><p>С включёнными экспериментальными функциями (Настройки → Эксперименты → «Экспериментальные функции») у проекта появляется кнопка «Собрать вместе»: друзья видят проект в «Друзьях» и правят его вместе с вами, а ставить его никому не нужно. Подробнее: <a href="/guide/connect.html#coop-build">Совместная сборка</a>.</p><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li><a href="/guide/modpacks.html">Модпаки</a>: установка, обновление и форматы</li><li><a href="/guide/collections.html">Сборки модов</a>: набор модов, который подбирается под любую версию</li></ul>',24)])])}const g=e(i,[["render",l]]);export{p as __pageData,g as default};
